// FR-4: every message is processed exactly once, even when the work is slow.
//
// The cursor is claimed from the bridge BEFORE anything slow runs. n8n's own
// static data cannot do this: it is only written when an execution finishes,
// so while a 3-minute CV review was in flight, eight more 15-second polls all
// read the same stale cursor and reprocessed the same CV. The bridge writes
// the claim synchronously under a lock, so exactly one execution can win.
//
// Returning [] stops the branch, so nothing is sent when nothing is new.

const cfg = $('Config').first().json;

const msgs = [];
for (const item of $input.all()) {
  const arr = Array.isArray(item.json) ? item.json : [item.json];
  for (const m of arr) {
    if (m && m.id) msgs.push(m);
  }
}

// Snowflakes are numeric strings - compare as BigInt, never lexically.
msgs.sort((a, b) => (BigInt(a.id) < BigInt(b.id) ? -1 : 1));

// Ignore Sanad's own replies, or it would answer itself every 15 seconds.
const human = msgs.filter((m) => !(m.author && m.author.bot));
if (human.length === 0) return [];

// Newest message only. Anything older is either already handled or superseded.
const m = human[human.length - 1];

const claim = await this.helpers.httpRequest({
  method: 'POST',
  url: `${cfg.bridge}/claim`,
  body: { message_id: m.id },
  json: true,
});

if (!claim || claim.claimed !== true) return [];

const atts = (m.attachments || []).filter((a) => /\.pdf$/i.test(a.filename || ''));

return [{
  json: {
    message_id: m.id,
    content: m.content || '',
    is_first_contact: claim.is_first_contact === true,
    session_id: claim.session_id || null,
    has_cv: atts.length > 0,
    attachment_name: atts.length ? atts[0].filename : null,
    attachment_url: atts.length ? atts[0].url : null,
    cv_name: atts.length ? `cv-${m.id}.pdf` : null,
    dm_channel_id: cfg.dm_channel_id,
    workspace: cfg.workspace,
    bridge: cfg.bridge,
  },
}];

// A CV arrived: open a NEW Claude Code session and hand it the file path.
// The session id is persisted through the bridge, not n8n static data, so the
// next message can resume this exact conversation.

const m = $('Pick New Messages').first().json;
// Single source of truth: the path the bridge actually wrote to.
const cvPath = $('Fetch CV to Workspace').first().json.path;

const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = Math.floor(Math.random() * 16);
  const v = c === 'x' ? r : ((r & 0x3) | 0x8);
  return v.toString(16);
});

await this.helpers.httpRequest({
  method: 'POST',
  url: `${m.bridge}/state`,
  body: { patch: { session_id: uuid, cv_path: cvPath, cv_name: m.cv_name } },
  json: true,
});

const prompt = [
  'You are Sanad, talking to someone in a Discord DM. They cannot see a terminal - only your chat messages.',
  '',
  'Use the cv-reviewer skill to review the CV at this path:',
  cvPath,
  '',
  'How to behave here:',
  '- Ask your intake questions ONE at a time, in a single short message. Three questions maximum.',
  '- Never mention file paths, scripts, tools, or that you are a CLI.',
  '- Keep every message under 1200 characters.',
  '- Plain text with light Discord markdown (**bold**, *italic*, bullets). No code fences.',
  '',
  'When you have everything you need, deliver the review in EXACTLY this format and nothing else:',
  '',
  '===SUMMARY===',
  '(a short friendly Discord message: the score out of 100, the three biggest problems, and one sentence on what happens next. Under 1200 characters.)',
  '===REPORT===',
  '(the complete review in Markdown - headings, tables, every finding. This becomes a PDF, so length is fine.)',
  '',
  'Right now: read the CV, then ask your FIRST intake question. Reply with just that question.',
].join('\n');

return [{ json: { ...m, session_id: uuid, prompt } }];

// Not a CV: resume the existing Claude Code session. This is how intake answers,
// the "yes fix it" approval and general questions are all handled - Claude Code
// owns the conversation, n8n just carries the text.

const m = $('Pick New Messages').first().json;

let sessionId = m.session_id;
let prompt;

if (!sessionId) {
  // Chatting before any CV was sent. Start a session so Sanad can still answer.
  sessionId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.floor(Math.random() * 16);
    const v = c === 'x' ? r : ((r & 0x3) | 0x8);
    return v.toString(16);
  });

  await this.helpers.httpRequest({
    method: 'POST',
    url: `${m.bridge}/state`,
    body: { patch: { session_id: sessionId } },
    json: true,
  });

  prompt = [
    'You are Sanad, a helper in a Discord DM. You review and rewrite CVs, then match them against live freelance projects.',
    'No CV has been sent yet - if they are ready, ask them to send one as a PDF.',
    'Keep replies under 1200 characters, plain text with light Discord markdown, no code fences.',
    '',
    'The person said:',
    m.content,
  ].join('\n');
} else {
  prompt = [
    m.content,
    '',
    '(Reminder: you are Sanad in a Discord DM. Under 1200 characters. When you deliver the CV review, use the ===SUMMARY=== / ===REPORT=== format exactly as instructed.)',
  ].join('\n');
}

return [{ json: { ...m, session_id: sessionId, prompt } }];

// R-5 discipline: never trust the shape of an LLM response. Validate first,
// then decide whether this turn is a chat reply or the finished review.

const r = $input.first().json;
const m = $('Pick New Messages').first().json;

if (!r || r.ok !== true) {
  throw new Error('Bridge call failed: ' + JSON.stringify(r && r.error ? r.error : r).slice(0, 400));
}

const out = String(r.output || '').trim();
if (!out) throw new Error('Bridge returned an empty response.');

const S = '===SUMMARY===';
const R = '===REPORT===';

let hasReport = out.includes(R);
let summary = out;
let report = '';

if (hasReport) {
  const si = out.indexOf(S);
  const ri = out.indexOf(R);
  summary = (si >= 0 ? out.slice(si + S.length, ri) : out.slice(0, ri)).trim();
  report = out.slice(ri + R.length).trim();

  // Guard: the marker appeared but the body did not. Treat it as chat rather
  // than shipping an empty PDF.
  if (report.length < 40) {
    hasReport = false;
    summary = out;
    report = '';
  }
}

// Discord hard-caps a message at 2000 characters.
if (summary.length > 1900) summary = summary.slice(0, 1890) + '\n\u2026';

return [{
  json: {
    has_report: hasReport,
    summary,
    report,
    session_id: r.session_id,
    resumed: r.resumed,
    dm_channel_id: m.dm_channel_id,
    bridge: m.bridge,
    workspace: m.workspace,
    pdf_name: `sanad-review-${m.message_id}.pdf`,
  },
}];
